CREATE FUNCTION fyf_verify_variant(pid integer) RETURNS void LANGUAGE plpgsql AS $$
DECLARE p products%ROWTYPE; f product_families%ROWTYPE; expected integer; actual integer; canonical text;
BEGIN
 SELECT * INTO p FROM products WHERE id=pid;
 IF NOT FOUND THEN RETURN; END IF;
 IF p.family_id IS NULL THEN
   IF EXISTS(SELECT 1 FROM product_variant_values WHERE product_id=pid) THEN RAISE EXCEPTION 'Simple product has variant options' USING ERRCODE='23514'; END IF;
   RETURN;
 END IF;
 SELECT * INTO f FROM product_families WHERE id=p.family_id;
 IF p.category_id<>f.category_id OR lower(btrim(coalesce(p.brand,'')))<>lower(btrim(coalesce(f.brand,''))) THEN
   RAISE EXCEPTION 'Family category/brand mismatch' USING ERRCODE='23514';
 END IF;
 SELECT count(*) INTO expected FROM family_attributes WHERE family_id=p.family_id;
 SELECT count(*),string_agg(option_id::text,',' ORDER BY attribute_id) INTO actual,canonical FROM product_variant_values WHERE product_id=pid;
 IF expected=0 OR expected<>actual OR p.variant_key IS DISTINCT FROM canonical THEN
   RAISE EXCEPTION 'Incomplete or noncanonical variant combination' USING ERRCODE='23514';
 END IF;
END $$;
--> statement-breakpoint
CREATE FUNCTION fyf_check_variant_row() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_TABLE_NAME='products' THEN PERFORM fyf_verify_variant(NEW.id);
 ELSE
   IF TG_OP <> 'INSERT' THEN PERFORM fyf_verify_variant(OLD.product_id); END IF;
   IF TG_OP <> 'DELETE' THEN PERFORM fyf_verify_variant(NEW.product_id); END IF;
 END IF;
 RETURN NULL;
END $$;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER products_variant_insert_check AFTER INSERT ON products DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fyf_check_variant_row();
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER products_variant_update_check AFTER UPDATE ON products DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN (OLD.family_id IS DISTINCT FROM NEW.family_id OR OLD.variant_key IS DISTINCT FROM NEW.variant_key OR OLD.category_id IS DISTINCT FROM NEW.category_id OR OLD.brand IS DISTINCT FROM NEW.brand) EXECUTE FUNCTION fyf_check_variant_row();
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER product_variant_values_check AFTER INSERT OR UPDATE OR DELETE ON product_variant_values DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fyf_check_variant_row();
