CREATE FUNCTION fyf_check_family_members() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE pid integer; fid integer;
BEGIN
 IF TG_TABLE_NAME='product_families' THEN fid:=NEW.id; ELSE fid:=coalesce(NEW.family_id,OLD.family_id); END IF;
 FOR pid IN SELECT id FROM products WHERE family_id=fid LOOP PERFORM fyf_verify_variant(pid); END LOOP;
 RETURN NULL;
END $$;
