CREATE FUNCTION fyf_preserve_product_identity() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.name IS DISTINCT FROM NEW.name OR OLD.brand IS DISTINCT FROM NEW.brand OR OLD.unit_measure IS DISTINCT FROM NEW.unit_measure
   OR (OLD.family_id IS NOT NULL AND (OLD.family_id IS DISTINCT FROM NEW.family_id OR OLD.variant_key IS DISTINCT FROM NEW.variant_key)) THEN
   IF EXISTS(SELECT 1 FROM sale_details WHERE product_id=OLD.id) OR EXISTS(SELECT 1 FROM online_order_items WHERE product_id=OLD.id) OR EXISTS(SELECT 1 FROM inventory_movements WHERE product_id=OLD.id) THEN
     RAISE EXCEPTION 'Historical product identity cannot change' USING ERRCODE='23514';
   END IF;
 END IF;
 RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER products_preserve_identity BEFORE UPDATE ON products FOR EACH ROW EXECUTE FUNCTION fyf_preserve_product_identity();
--> statement-breakpoint
CREATE FUNCTION fyf_preserve_used_option() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.label IS DISTINCT FROM NEW.label OR OLD.attribute_id IS DISTINCT FROM NEW.attribute_id THEN
   IF EXISTS(SELECT 1 FROM product_variant_values WHERE option_id=OLD.id) THEN RAISE EXCEPTION 'Used option identity cannot change' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER family_options_preserve_identity BEFORE UPDATE ON family_attribute_options FOR EACH ROW EXECUTE FUNCTION fyf_preserve_used_option();
